steps.script:
try {
$d='C:\TTiTTulares\image-approval-receipts'
$a=@(Get-ChildItem -LiteralPath $d -File -Filter '*.json' -ErrorAction Stop | Where-Object { $_.Name -match '^(tt|tr)-img-' })
$recent=@($a | Where-Object { $_.LastWriteTimeUtc -ge [datetime]::UtcNow.AddHours(-1) })
$last=@($a | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 4 | ForEach-Object { $_.Name })
$o=@{all=$a.Count;lastHour=$recent.Count;lastFour=$last}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 3))
} catch {
Write-Output ('TTRESULT:'+(@{error=($_.Exception.Message -replace 'https?://\S+','[URL]')}|ConvertTo-Json -Compress))
}
